-- Historial del libro de actas: evaluaciones con trabajo escrito del sistema de Titulación anterior (respaldo del 24-03-2021),
-- 1254 registros (alumno por acta) de 1988-08-12 a 2020-12-10. Generado por
-- tools/importar_titulacion_anterior.py. Repetible y sin sobrescribir: los registros que ya existen en tit_historico (misma
-- licenciatura y cuenta, y misma acta o fecha) solo reciben lo que tienen vacío —nunca los que ya tienen constancias—, y los demás
-- se agregan con hoja «SISTEMA ANTERIOR». Con dos o más asesores el sistema anterior no distingue director de codirector: esos registros
-- llevan los nombres pero no los correos, y quedan pendientes en el visor hasta que el personal confirme el rol.
-- El número de acta se omite cuando se repite en otra evaluación de la misma licenciatura (libros antiguos).

DROP TEMPORARY TABLE IF EXISTS tmp_hist_ant;
CREATE TEMPORARY TABLE tmp_hist_ant (
  fila INT UNSIGNED NOT NULL,
  carrera VARCHAR(20) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  acta INT UNSIGNED NULL,
  acta_dudosa TINYINT NOT NULL DEFAULT 0,
  ambiguo TINYINT NOT NULL DEFAULT 0,
  alumno VARCHAR(160) NOT NULL DEFAULT '',
  cuenta VARCHAR(12) NOT NULL DEFAULT '',
  modalidad VARCHAR(30) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  modalidad_origen VARCHAR(60) NOT NULL DEFAULT '',
  fecha_examen DATE NULL,
  titulo VARCHAR(500) NOT NULL DEFAULT '',
  director VARCHAR(160) NOT NULL DEFAULT '', director_email VARCHAR(120) NOT NULL DEFAULT '',
  codirector VARCHAR(160) NOT NULL DEFAULT '', codirector_email VARCHAR(120) NOT NULL DEFAULT '',
  presidente VARCHAR(160) NOT NULL DEFAULT '', presidente_email VARCHAR(120) NOT NULL DEFAULT '',
  secretario VARCHAR(160) NOT NULL DEFAULT '', secretario_email VARCHAR(120) NOT NULL DEFAULT '',
  vocal VARCHAR(160) NOT NULL DEFAULT '', vocal_email VARCHAR(120) NOT NULL DEFAULT '',
  director_sg VARCHAR(160) NOT NULL DEFAULT '', codirector_sg VARCHAR(160) NOT NULL DEFAULT '', presidente_sg VARCHAR(160) NOT NULL DEFAULT '',
  secretario_sg VARCHAR(160) NOT NULL DEFAULT '', vocal_sg VARCHAR(160) NOT NULL DEFAULT '',
  PRIMARY KEY (fila)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- 0) Los correos del sistema anterior son marcadores («sin@correo.com.mx»): se toman de las cuentas de la plataforma cuando el
--    nombre (sin grado) coincide con una sola cuenta activa. Con dos o más asesores no se asigna ninguno.
UPDATE tmp_hist_ant t SET t.director_email = IFNULL((SELECT MIN(u.email) FROM usuarios u WHERE u.activo = 1 AND u.nombre COLLATE utf8mb4_unicode_ci = t.director_sg HAVING COUNT(*) = 1), '') WHERE t.ambiguo = 0 AND t.director_sg <> '' AND t.director_email = '';
UPDATE tmp_hist_ant t SET t.codirector_email = IFNULL((SELECT MIN(u.email) FROM usuarios u WHERE u.activo = 1 AND u.nombre COLLATE utf8mb4_unicode_ci = t.codirector_sg HAVING COUNT(*) = 1), '') WHERE t.ambiguo = 0 AND t.codirector_sg <> '' AND t.codirector_email = '';
UPDATE tmp_hist_ant t SET t.presidente_email = IFNULL((SELECT MIN(u.email) FROM usuarios u WHERE u.activo = 1 AND u.nombre COLLATE utf8mb4_unicode_ci = t.presidente_sg HAVING COUNT(*) = 1), '') WHERE t.ambiguo = 0 AND t.presidente_sg <> '' AND t.presidente_email = '';
UPDATE tmp_hist_ant t SET t.secretario_email = IFNULL((SELECT MIN(u.email) FROM usuarios u WHERE u.activo = 1 AND u.nombre COLLATE utf8mb4_unicode_ci = t.secretario_sg HAVING COUNT(*) = 1), '') WHERE t.ambiguo = 0 AND t.secretario_sg <> '' AND t.secretario_email = '';
UPDATE tmp_hist_ant t SET t.vocal_email = IFNULL((SELECT MIN(u.email) FROM usuarios u WHERE u.activo = 1 AND u.nombre COLLATE utf8mb4_unicode_ci = t.vocal_sg HAVING COUNT(*) = 1), '') WHERE t.ambiguo = 0 AND t.vocal_sg <> '' AND t.vocal_email = '';

-- 1) Completar lo vacío de los registros que ya existen y no tienen constancias.
UPDATE tit_historico h JOIN tmp_hist_ant t ON h.carrera = t.carrera AND h.cuenta = t.cuenta AND (h.acta = t.acta OR h.fecha_examen = t.fecha_examen) AND (h.modalidad IS NULL OR h.modalidad = '' OR h.modalidad = t.modalidad)
SET h.acta = IF(h.acta IS NULL AND t.acta_dudosa = 0, t.acta, h.acta),
    h.fecha_examen = IFNULL(h.fecha_examen, t.fecha_examen),
    h.modalidad = IFNULL(NULLIF(h.modalidad, ''), t.modalidad),
    h.titulo = IF(h.titulo = '', t.titulo, h.titulo),
    h.director_email = IF(h.director_email = '' AND (h.director = '' OR h.director = t.director), t.director_email, h.director_email),
    h.director = IF(h.director = '', t.director, h.director),
    h.codirector_email = IF(h.codirector_email = '' AND (h.codirector = '' OR h.codirector = t.codirector), t.codirector_email, h.codirector_email),
    h.codirector = IF(h.codirector = '', t.codirector, h.codirector),
    h.presidente_email = IF(h.presidente_email = '' AND (h.presidente = '' OR h.presidente = t.presidente), t.presidente_email, h.presidente_email),
    h.presidente = IF(h.presidente = '', t.presidente, h.presidente),
    h.secretario_email = IF(h.secretario_email = '' AND (h.secretario = '' OR h.secretario = t.secretario), t.secretario_email, h.secretario_email),
    h.secretario = IF(h.secretario = '', t.secretario, h.secretario),
    h.vocal_email = IF(h.vocal_email = '' AND (h.vocal = '' OR h.vocal = t.vocal), t.vocal_email, h.vocal_email),
    h.vocal = IF(h.vocal = '', t.vocal, h.vocal)
WHERE h.tramite_id IS NULL;

-- 2) Agregar los que no existen.
  director, director_email, codirector, codirector_email, presidente, presidente_email, secretario, secretario_email, vocal, vocal_email)
SELECT 'SISTEMA ANTERIOR', t.fila, t.carrera,
  IF(t.acta_dudosa = 0 AND NOT EXISTS (SELECT 1 FROM tit_historico x WHERE x.carrera = t.carrera AND x.acta = t.acta AND x.cuenta <> t.cuenta), t.acta, NULL),
  t.alumno, t.cuenta, t.modalidad, t.modalidad_origen, t.fecha_examen, t.titulo,
  t.director, t.director_email, t.codirector, t.codirector_email, t.presidente, t.presidente_email, t.secretario, t.secretario_email, t.vocal, t.vocal_email
FROM tmp_hist_ant t
WHERE NOT EXISTS (SELECT 1 FROM tit_historico h WHERE h.carrera = t.carrera AND h.cuenta = t.cuenta AND (h.acta = t.acta OR h.fecha_examen = t.fecha_examen) AND (h.modalidad IS NULL OR h.modalidad = '' OR h.modalidad = t.modalidad));

DROP TEMPORARY TABLE tmp_hist_ant;
